INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('gate-puzzler','basic','What does a NOT gate do?',ARRAY['Inverts the input','Buffers the input','Adds two inputs','Multiplies inputs'],0,'A NOT gate outputs the inverse of its input.',10),
('gate-puzzler','basic','Which gate outputs 1 only when both inputs are 1?',ARRAY['AND','OR','XOR','NAND'],0,'AND requires both inputs high.',10),
('gate-puzzler','basic','How many inputs does a standard NOT gate have?',ARRAY['1','2','3','4'],0,'NOT is a single-input gate.',10),
('gate-puzzler','basic','What is the output of OR gate when both inputs are 0?',ARRAY['0','1','High impedance','Undefined'],0,'OR outputs 0 only when all inputs are 0.',10),
('gate-puzzler','basic','NAND gate is the combination of which two gates?',ARRAY['AND + NOT','OR + NOT','XOR + NOT','NOR + NOT'],0,'NAND is AND followed by NOT.',10),
('gate-puzzler','basic','Which gate outputs 0 only when both inputs are 1?',ARRAY['NAND','AND','OR','XOR'],0,'NAND outputs 0 only when all inputs are 1.',10),
('gate-puzzler','basic','What does XOR output when both inputs are the same?',ARRAY['0','1','High-Z','Depends on input'],0,'XOR outputs 0 when inputs are equal.',10),
('gate-puzzler','basic','How many input combinations does a 2-input truth table have?',ARRAY['4','2','8','16'],0,'2^2 = 4 combinations.',10),
('gate-puzzler','basic','Which symbol represents an AND gate?',ARRAY['D-shaped','Shield-shaped','Triangle','Oval'],0,'AND gates use a D-shaped symbol.',10),
('gate-puzzler','basic','What is the output of a NOR gate with inputs 1 and 0?',ARRAY['0','1','High-Z','Undefined'],0,'NOR outputs 0 if any input is 1.',10),
('gate-puzzler','basic','A buffer gate does what?',ARRAY['Passes input unchanged','Inverts input','ANDs inputs','ORs inputs'],0,'A buffer passes the signal through.',10),
('gate-puzzler','basic','Which gate is known as the universal gate?',ARRAY['NAND','XOR','OR','NOT'],0,'NAND can implement any logic function.',10),
