('gate-puzzler','basic','How many rows in a 3-input truth table?',ARRAY['8','4','16','32'],0,'2^3 = 8 rows.',10),
('gate-puzzler','basic','Which gate gives 1 when inputs differ?',ARRAY['XOR','AND','OR','NAND'],0,'XOR outputs 1 when inputs differ.',10),
('gate-puzzler','basic','What is De Morgan''s first law?',ARRAY['NOT(A AND B) = NOT A OR NOT B','A AND B = A OR B','NOT(A OR B) = A AND B','A XOR B = A NAND B'],0,'De Morgan: complement of AND equals OR of complements.',10),
('gate-puzzler','basic','Which gate has a bubble at its output?',ARRAY['NAND','AND','OR','XOR'],0,'The bubble indicates inversion.',10),
